mapper.select:
/* selectMasterMdCpAgentCommunityInfoList */ SELECT MAX(B.COM_NAME_LOC) AS COM_NAME , MAX(B.COM_CODE) AS COM_CODE , MAX(B.IRS_NO) AS IRS_NO , MAX(B.CEO_NAME_LOC) AS CEO_NAME , MAX(B.ADDRESS_LOC) AS ADDRESS FROM ICOMCMPY B WHERE 1=1
AND B.COM_CODE = #{com_code}
AND B.COM_CODE = ''

/* selectMasterMdCpAgentCommunityPopList */ SELECT A.AGENT , (SELECT COM_NAME_LOC FROM ICOMCMPY B WHERE B.COM_CODE = A.AGENT) AS AGENT_NAME , (SELECT C.TEXT1 FROM ICOMCOD1 C WHERE A.TYPE = C.CODE AND C.TYPE = 'M201') AS TYPE_NAME , A.TYPE , (SELECT D.USER_NAME_LOC FROM ICOMLUSR D WHERE A.USER_ID = D.USER_ID) AS USER_NAME , A.USER_ID , A.REVISION , DECODE(A.REVISION, 0, '본문', '댓글') AS REVISION_TYPE , A.ADD_DATM , A.CHANGE_DATM , '댓글('||(SELECT COUNT(*)-1 FROM KEP_AGENT_COMMUNITY E WHERE A.AGENT = E.AGENT AND A.SEQ = E.SEQ AND E.STATUS <> 'D')||') '||SUBSTR(A.CONTEXT,1,200)||DECODE(SIGN(LENGTH(A.CONTEXT)-200),-1,'','...') AS CONTENTS , (SELECT COUNT(*)-1 AS REVISION FROM KEP_AGENT_COMMUNITY E WHERE A.AGENT = E.AGENT AND A.SEQ = E.SEQ AND E.STATUS <> 'D') AS COMMENT_COUNT , A.SEQ FROM KEP_AGENT_COMMUNITY A WHERE 1=1 AND STATUS <> 'D'
AND A.AGENT = #{com_code}
AND TO_CHAR(A.ADD_DATM,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND TO_CHAR(A.ADD_DATM,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND A.REVISION = 0
AND A.TYPE = #{st_gubun_code}
AND A.USER_ID = #{st_kep_user_id}
ORDER BY A.SEQ DESC, A.REVISION ASC, A.ADD_DATM DESC

mapper.update:


				SELECT NVL(MAX(SEQ),0)+1 AS SEQ FROM KEP_AGENT_COMMUNITY WHERE AGENT = #{com_code}



 		 	/*insertMasterMdCpAgentCommunityPopContext*/
 		 	INSERT INTO KEP_AGENT_COMMUNITY(	      		
	 		 	AGENT
	 		 	,SEQ
	 		 	,REVISION
	 		 	,STATUS
	 		 	,TYPE
	 		 	,USER_ID
	 		 	,DEPARTMENT
	 		 	,CONTEXT
	 		 	,ADD_DATM
	 		 	,CHANGE_DATM   
			)
			VALUES
			(
	 		 	#{com_code}
				,#{SEQ}
				,0
				,'C'
				,#{st_agent_type_flag}
				,#{st_user_id}
				,#{st_user_dept}
				,#{CONTEXT}
				,SYSDATE
				,SYSDATE
			)


/*deleteMasterMdCpAgentCommunityPopContext*/
UPDATE	KEP_AGENT_COMMUNITY
SET		STATUS = 'D'
		, CHANGE_DATM = SYSDATE
WHERE	AGENT = #{com_code} 
AND 	SEQ = #{SEQ}


AND 	REVISION = #{st_comment_revision}


/*updateMasterMdCpAgentCommunityPopContext*/
UPDATE	KEP_AGENT_COMMUNITY
SET		STATUS = 'R'
		, TYPE = #{st_agent_type_flag}
		, CONTEXT = #{CONTEXT}
		, CHANGE_DATM = SYSDATE
WHERE	AGENT = #{com_code} 
AND 	SEQ = #{SEQ}
AND		REVISION = 0

mapper.select:
/* selectMasterMdCpAgentCommunityPopComment */ SELECT A.USER_ID AS COMMENT_USER_ID , (SELECT D.USER_NAME_LOC FROM ICOMLUSR D WHERE A.USER_ID = D.USER_ID) AS COMMENT_USER_NAME , A.REVISION AS COMMENT_REVISION , A.CONTEXT AS CONTENTS , A.ADD_DATM AS COMMENT_ADD_DATM , (SELECT COUNT(*)-1 AS REVISION FROM KEP_AGENT_COMMUNITY E WHERE A.AGENT = E.AGENT AND A.SEQ = E.SEQ AND E.STATUS <> 'D') AS COMMENT_COUNT FROM KEP_AGENT_COMMUNITY A WHERE 1=1 AND STATUS <> 'D' AND AGENT = #{com_code} AND SEQ = #{SEQ}
AND A.REVISION = #{st_comment_revision}
AND A.REVISION > 0
ORDER BY REVISION

